from __future__ import annotations

DASHBOARD_HTML = r'''<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <meta name="color-scheme" content="light" />
  <title>LedgerBox · 账单匣</title>
  <style>
    :root{--bg:#f5f2ea;--surface:#fffdf8;--text:#1f2925;--muted:#707772;--line:#dedbd2;--accent:#1f4a3a;--accent2:#8c3d32;--warn:#a36820;--radius:18px;--shadow:0 18px 45px rgba(37,43,39,.07)}
    *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,"PingFang SC","Microsoft YaHei",system-ui,sans-serif}.wrap{max-width:1180px;margin:auto;padding:28px 20px 60px}.top{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:26px}.brand h1{font-family:Georgia,"Noto Serif SC",serif;font-size:32px;margin:0 0 7px}.brand p,.muted{color:var(--muted)}button,select,input{font:inherit}button{cursor:pointer;border:0}.actions{display:flex;gap:10px;flex-wrap:wrap}.btn{min-height:42px;padding:0 15px;border-radius:12px;background:var(--accent);color:white}.btn.line{background:var(--surface);color:var(--text);border:1px solid var(--line)}.btn:disabled{opacity:.5;cursor:not-allowed}.grid{display:grid;gap:14px}.stats{grid-template-columns:repeat(4,1fr)}.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:18px;box-shadow:var(--shadow)}.stat .label{font-size:13px;color:var(--muted)}.stat .value{font-family:Georgia,"Noto Serif SC",serif;font-size:28px;margin-top:8px;font-variant-numeric:tabular-nums}.green{color:var(--accent)}.red{color:var(--accent2)}.two{grid-template-columns:1fr 1fr;margin-top:18px}.card h2{font-size:17px;margin:0 0 14px}.bars{display:flex;flex-direction:column;gap:11px}.barrow{display:grid;grid-template-columns:90px 1fr 90px;gap:10px;align-items:center;font-size:13px}.track{height:9px;border-radius:99px;background:#ece9e1;overflow:hidden}.fill{height:100%;border-radius:99px;background:var(--accent)}.amt{text-align:right;font-variant-numeric:tabular-nums}.section{margin-top:18px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.section-head h2{margin:0}.select{min-height:42px;border:1px solid var(--line);background:var(--surface);border-radius:12px;padding:0 12px;color:var(--text)}.notice{display:none;margin:14px 0;border:1px solid #e2c99c;background:#fff8e8;border-radius:14px;padding:12px 14px;color:#78501e}.notice.show{display:block}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:var(--radius);background:var(--surface)}table{width:100%;border-collapse:collapse;min-width:760px;font-size:13px}th,td{text-align:left;padding:12px 14px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:600;background:#fbf9f4;position:sticky;top:0}tr:last-child td{border-bottom:0}.badge{display:inline-flex;border-radius:99px;padding:3px 8px;font-size:12px;background:#ece9e1}.badge.waiting_password{background:#fff1cf;color:#805217}.badge.error{background:#fce7e4;color:#8c3d32}.badge.processed,.badge.imported{background:#e5f0e9;color:#28543d}.pending{display:grid;gap:10px}.pending-item{display:flex;justify-content:space-between;align-items:center;gap:12px;border:1px solid var(--line);border-radius:14px;padding:12px}.pending-main{min-width:0}.pending-main strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pending-main small{color:var(--muted)}dialog{border:1px solid var(--line);border-radius:18px;padding:0;background:var(--surface);color:var(--text);box-shadow:0 35px 90px rgba(0,0,0,.2);width:min(430px,calc(100vw - 32px))}dialog::backdrop{background:rgba(18,24,21,.36)}.modal{padding:22px}.modal h3{margin:0 0 8px}.modal p{color:var(--muted);font-size:13px}.modal input{width:100%;min-height:44px;border-radius:12px;border:1px solid var(--line);padding:0 12px;background:white}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}.empty{color:var(--muted);padding:20px;text-align:center}.pager{display:flex;gap:8px;align-items:center;justify-content:flex-end;margin-top:10px;font-size:13px;color:var(--muted)}@media(max-width:800px){.stats{grid-template-columns:1fr 1fr}.two{grid-template-columns:1fr}.top{flex-direction:column}.actions{width:100%}.actions .btn{flex:1}.wrap{padding:20px 14px 42px}}@media(max-width:480px){.stats{grid-template-columns:1fr}.brand h1{font-size:28px}.barrow{grid-template-columns:72px 1fr 78px}}
  </style>
</head>
<body>
<div class="wrap">
  <header class="top">
    <div class="brand"><h1>账单匣</h1><p>微信 · 支付宝 · 招行，官方账单统一归集</p></div>
    <div class="actions"><button id="syncBtn" class="btn">检查新账单</button><button id="tokenBtn" class="btn line">访问设置</button></div>
  </header>
  <div id="notice" class="notice"></div>
  <div class="section-head"><div></div><select id="month" class="select"></select></div>
  <section class="grid stats">
    <div class="card stat"><div class="label">支出</div><div id="expense" class="value red">—</div></div>
    <div class="card stat"><div class="label">收入</div><div id="income" class="value green">—</div></div>
    <div class="card stat"><div class="label">净额</div><div id="net" class="value">—</div></div>
    <div class="card stat"><div class="label">内部转移</div><div id="transfer" class="value">—</div></div>
  </section>
  <section class="grid two">
    <div class="card"><h2>分类支出</h2><div id="categories" class="bars"></div></div>
    <div class="card"><h2>每日支出</h2><div id="days" class="bars"></div></div>
  </section>
  <section class="card section"><div class="section-head"><h2>待处理</h2><span id="pendingCount" class="muted"></span></div><div id="pending" class="pending"></div></section>
  <section class="section"><div class="section-head"><h2>流水</h2><span id="txCount" class="muted"></span></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>平台</th><th>对方 / 描述</th><th>方向</th><th>金额</th><th>分类</th></tr></thead><tbody id="txBody"></tbody></table></div><div class="pager"><button id="prev" class="btn line">上一页</button><span id="pageText"></span><button id="next" class="btn line">下一页</button></div></section>
  <section class="section"><div class="section-head"><h2>最近导入</h2></div><div class="table-wrap"><table><thead><tr><th>收到时间</th><th>主题</th><th>附件</th><th>状态</th></tr></thead><tbody id="importBody"></tbody></table></div></section>
</div>
<dialog id="unlockDialog"><form method="dialog" class="modal" id="unlockForm"><h3>输入账单解压密码</h3><p id="unlockName"></p><input id="unlockPassword" type="password" autocomplete="off" placeholder="解压密码" required><div class="modal-actions"><button class="btn line" value="cancel">取消</button><button id="unlockSubmit" class="btn" value="default">解压并导入</button></div></form></dialog>
<dialog id="tokenDialog"><form method="dialog" class="modal" id="tokenForm"><h3>访问设置</h3><p>如果 LedgerBox 配置了 api.token，请在这里输入。仅保存在当前浏览器的 sessionStorage。</p><input id="tokenInput" type="password" autocomplete="off" placeholder="API Token"><div class="modal-actions"><button class="btn line" value="cancel">取消</button><button class="btn" value="default">保存</button></div></form></dialog>
<script>
const $=s=>document.querySelector(s);const state={month:'',offset:0,limit:50,total:0,unlockHash:''};
const money=n=>'¥ '+Number(n||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function headers(json=false){const h={};const token=sessionStorage.getItem('ledgerbox-token');if(token)h.Authorization='Bearer '+token;if(json)h['Content-Type']='application/json';return h}
async function api(path,options={}){const r=await fetch(path,{...options,headers:{...headers(Boolean(options.body)),...(options.headers||{})}});if(r.status===401){showNotice('需要 API Token，请点击“访问设置”填写。');throw new Error('unauthorized')}const b=await r.json();if(!r.ok||!b.ok)throw new Error(b.error||'请求失败');return b.data}
function showNotice(text){const n=$('#notice');n.textContent=text;n.classList.add('show')}function clearNotice(){$('#notice').classList.remove('show')}
function bars(el,data){const entries=Object.entries(data||{});if(!entries.length){el.innerHTML='<div class="empty">暂无数据</div>';return}const max=Math.max(...entries.map(x=>Number(x[1])));el.innerHTML=entries.slice(0,12).map(([k,v])=>`<div class="barrow"><span>${esc(k.length>10?k.slice(0,10)+'…':k)}</span><div class="track"><div class="fill" style="width:${max?Number(v)/max*100:0}%"></div></div><span class="amt">${money(v)}</span></div>`).join('')}
async function loadSummary(){const q=state.month?'?month='+encodeURIComponent(state.month):'';const d=await api('/api/summary'+q);if(!state.month)state.month=d.month;const sel=$('#month');sel.innerHTML=(d.months||[]).map(m=>`<option ${m===state.month?'selected':''}>${esc(m)}</option>`).join('')||`<option>${esc(d.month)}</option>`;$('#expense').textContent=money(d.expense);$('#income').textContent=money(d.income);$('#net').textContent=money(d.net);$('#transfer').textContent=money(d.transfer);bars($('#categories'),d.by_category);const dayObj={};Object.entries(d.by_day||{}).slice(-12).forEach(([k,v])=>dayObj[k.slice(5)]=v);bars($('#days'),dayObj)}
async function loadTx(){const q=new URLSearchParams({limit:String(state.limit),offset:String(state.offset)});if(state.month)q.set('month',state.month);const d=await api('/api/transactions?'+q);state.total=d.total;$('#txCount').textContent=`${d.total} 笔`;$('#txBody').innerHTML=d.items.length?d.items.map(t=>`<tr><td>${esc(t.time)}</td><td>${esc(t.platform)}</td><td><strong>${esc(t.counterparty||t.description||'—')}</strong><div class="muted">${esc(t.description||t.raw_type||'')}</div></td><td>${esc(t.direction)}</td><td>${money(t.amount)}</td><td>${esc(t.category||'未分类')}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">暂无流水</td></tr>';const p=Math.floor(state.offset/state.limit)+1;const pages=Math.max(1,Math.ceil(state.total/state.limit));$('#pageText').textContent=`${p} / ${pages}`;$('#prev').disabled=state.offset===0;$('#next').disabled=state.offset+state.limit>=state.total}
async function loadPending(){const d=await api('/api/pending');$('#pendingCount').textContent=d.length?`${d.length} 个待处理`:'';$('#pending').innerHTML=d.length?d.map(x=>`<div class="pending-item"><div class="pending-main"><strong>${esc(x.filename)}</strong><small>${esc(x.platform||'')} · <span class="badge ${esc(x.status)}">${esc(x.status)}</span> · ${esc(x.error||'')}</small></div>${x.status==='waiting_password'?`<button class="btn line unlock" data-hash="${esc(x.sha256)}" data-name="${esc(x.filename)}">输入密码</button>`:''}</div>`).join(''):'<div class="empty">没有等待密码或失败的账单</div>';document.querySelectorAll('.unlock').forEach(b=>b.onclick=()=>{state.unlockHash=b.dataset.hash;$('#unlockName').textContent=b.dataset.name;$('#unlockPassword').value='';$('#unlockDialog').showModal()})}
async function loadImports(){const d=await api('/api/imports?limit=30');$('#importBody').innerHTML=d.length?d.map(x=>`<tr><td>${esc(x.received_at||'—')}</td><td>${esc(x.subject||'—')}</td><td>${esc(x.attachment_count)}</td><td><span class="badge ${esc(x.status)}">${esc(x.status)}</span></td></tr>`).join(''):'<tr><td colspan="4" class="empty">暂无导入记录</td></tr>'}
async function reload(){clearNotice();try{await Promise.all([loadSummary(),loadPending(),loadImports()]);await loadTx()}catch(e){console.error(e)}}
$('#month').onchange=e=>{state.month=e.target.value;state.offset=0;reload()};$('#prev').onclick=()=>{state.offset=Math.max(0,state.offset-state.limit);loadTx()};$('#next').onclick=()=>{state.offset+=state.limit;loadTx()};
$('#syncBtn').onclick=async()=>{const b=$('#syncBtn');b.disabled=true;b.textContent='同步中…';clearNotice();try{const d=await api('/api/sync',{method:'POST',body:'{}'});showNotice(`同步完成：新增附件 ${d.new_attachments}，写入/更新 ${d.imported} 笔，等待密码 ${d.waiting_password}。`);await reload()}catch(e){if(e.message!=='unauthorized')showNotice('同步失败：'+e.message)}finally{b.disabled=false;b.textContent='检查新账单'}};
$('#unlockForm').onsubmit=async e=>{e.preventDefault();const p=$('#unlockPassword').value;if(!p)return;$('#unlockSubmit').disabled=true;try{const d=await api('/api/unlock',{method:'POST',body:JSON.stringify({sha256:state.unlockHash,password:p})});if(d.status!=='imported')showNotice(d.error||'密码可能不正确，请重试。');else showNotice(`解压成功，写入/更新 ${d.imported} 笔流水。`);$('#unlockDialog').close();await reload()}catch(err){showNotice('解压失败：'+err.message)}finally{$('#unlockSubmit').disabled=false}};
$('#tokenBtn').onclick=()=>{$('#tokenInput').value=sessionStorage.getItem('ledgerbox-token')||'';$('#tokenDialog').showModal()};$('#tokenForm').onsubmit=e=>{e.preventDefault();const v=$('#tokenInput').value.trim();if(v)sessionStorage.setItem('ledgerbox-token',v);else sessionStorage.removeItem('ledgerbox-token');$('#tokenDialog').close();reload()};
reload();
</script>
</body></html>'''
